<?php require __DIR__.'/inc/header.php';$title='Categories';$pdo=db();if(is_post()){verify_csrf();$name=trim((string)post('name'));$type=(string)post('type');if($name&&in_array($type,['gadgets','jersey','fashion'],true)){$pdo->prepare('INSERT OR IGNORE INTO categories(name,slug,type,sort_order) VALUES(?,?,?,0)')->execute([$name,slugify($name),$type]);flash('success','Category added.');redirect('/admin/categories.php');}}$rows=$pdo->query('SELECT c.*,COUNT(p.id) products FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id ORDER BY c.type,c.sort_order')->fetchAll();?><div class="flex justify-between items-center mb-6"><div><div class="text-xs tracking-[.2em] text-slate-400 font-black">CATALOG</div><h1 class="text-3xl font-black">Categories</h1></div></div><div class="grid lg:grid-cols-[360px_1fr] gap-6"><form method="post" class="bg-white border rounded-2xl p-5 h-fit"><?=csrf_input()?><div class="font-black">Add Category</div><input name="name" required placeholder="Category name" class="w-full mt-4 rounded-xl border-slate-200"><select name="type" class="w-full mt-3 rounded-xl border-slate-200"><option>gadgets</option><option>jersey</option><option>fashion</option></select><button class="w-full mt-4 rounded-xl bg-slate-950 text-white py-3 font-black">Add</button></form><div class="bg-white border rounded-2xl overflow-hidden"><div class="overflow-x-auto"><table class="w-full text-sm"><thead class="bg-slate-50"><tr><th class="p-3 text-left">Category</th><th class="p-3 text-left">Niche</th><th class="p-3 text-left">Products</th></tr></thead><tbody><?php foreach($rows as $r):?><tr class="border-t"><td class="p-3 font-bold"><?=e($r['name'])?></td><td class="p-3"><?=ucfirst(e($r['type']))?></td><td class="p-3"><?=$r['products']?></td></tr><?php endforeach;?></tbody></table></div></div></div><?php require __DIR__.'/inc/footer.php';?>
